INSERT INTO campuses (name, address) SELECT 'ESL TTT', 'Khu đô thị Lạc Hồng Phúc-Mỹ Hào-Hưng Yên' WHERE NOT EXISTS (SELECT 1 FROM campuses WHERE lower(trim(name)) = lower('ESL TTT'));
INSERT INTO teacher_campuses (teacher_id, campus_id) VALUES (63, (SELECT id FROM campuses WHERE lower(trim(name)) = lower('ESL TTT') LIMIT 1)) ON CONFLICT (teacher_id, campus_id) DO NOTHING;
INSERT INTO teachers (name, phone, subject, staff_role, status, avatar_tone) SELECT 'Ms. Diane', '', 'Tiếng Anh', 'foreign', 'active', 'lav' WHERE NOT EXISTS (SELECT 1 FROM teachers WHERE lower(trim(name)) = lower('Ms. Diane'));
INSERT INTO teacher_campuses (teacher_id, campus_id) VALUES ((SELECT id FROM teachers WHERE lower(trim(name)) = lower('Ms. Diane') LIMIT 1), (SELECT id FROM campuses WHERE lower(trim(name)) = lower('ESL TTT') LIMIT 1)) ON CONFLICT (teacher_id, campus_id) DO NOTHING;
INSERT INTO teachers (name, phone, subject, staff_role, status, avatar_tone) SELECT 'cô Huyền My', '0969931399', 'Tiếng Anh', 'teacher', 'active', 'mint' WHERE NOT EXISTS (SELECT 1 FROM teachers WHERE regexp_replace(phone, '\D', '', 'g') = '0969931399');
INSERT INTO teacher_campuses (teacher_id, campus_id) VALUES ((SELECT id FROM teachers WHERE regexp_replace(phone, '\D', '', 'g') = '0969931399' LIMIT 1), (SELECT id FROM campuses WHERE lower(trim(name)) = lower('ESL TTT') LIMIT 1)) ON CONFLICT (teacher_id, campus_id) DO NOTHING;
INSERT INTO classes (campus_id, name, course, teacher_id, assistant_id, foreign_teacher_id, schedule, weekdays, start_time, end_time, sessions_total, fee, room, capacity) SELECT (SELECT id FROM campuses WHERE lower(trim(name)) = lower('ESL TTT') LIMIT 1), 'Jolly 1', 'Academy', 63, NULL, (SELECT id FROM teachers WHERE lower(trim(name)) = lower('Ms. Diane') LIMIT 1), 'T5 · T7 · 17:00–18:30', 'T5,T7', '17:00', '18:30', 24, 6000000, '1', 15 WHERE NOT EXISTS (SELECT 1 FROM classes WHERE campus_id = (SELECT id FROM campuses WHERE lower(trim(name)) = lower('ESL TTT') LIMIT 1) AND lower(trim(name)) = lower('Jolly 1'));
