INSERT INTO accounts (full_name, email, role, status, password_hash) VALUES ('Quản lý cơ sở Hoàng Gia', 'hoanggia@esl-center.vn', 'academic', 'active', 'scrypt$afd4eac9f6c2eff118732b62162afef3$c44e68e572f076a55a9d1fbaf5b87eeff4b51bea0aa729553a8d4fd4f8f5a335bc2d64d9b3bce5de994e9706f7c3f133344cf6c296df8277e62d5fc83ddb6fc9') ON CONFLICT (email) DO UPDATE SET full_name = EXCLUDED.full_name, role = EXCLUDED.role, status = 'active', updated_at = now();
INSERT INTO account_campuses (account_id, campus_id) SELECT a.id, c.id FROM accounts a JOIN campuses c ON a.email = 'hoanggia@esl-center.vn' AND lower(trim(c.name)) = lower('ESL Hoàng Gia') ON CONFLICT (account_id, campus_id) DO NOTHING;
